import java.io.BufferedInputStream
import java.util.Arrays

private class FastScanner {
    private val input = BufferedInputStream(System.`in`)
    private val buffer = ByteArray(1 shl 16)
    private var length = 0
    private var pointer = 0

    private fun readByte(): Int {
        if (pointer >= length) {
            length = input.read(buffer)
            pointer = 0
            if (length <= 0) return -1
        }
        return buffer[pointer++].toInt()
    }

    fun nextLong(): Long {
        var c: Int
        do {
            c = readByte()
        } while (c <= 32)

        var sign = 1
        if (c == '-'.code) {
            sign = -1
            c = readByte()
        }

        var value = 0L
        while (c > 32) {
            value = value * 10 + (c - '0'.code)
            c = readByte()
        }
        return if (sign == 1) value else -value
    }
}

private fun generateSums(values: LongArray, modulus: Long): LongArray {
    val size = 1 shl values.size
    val sums = LongArray(size)

    for (mask in 1 until size) {
        val bit = mask and -mask
        val index = Integer.numberOfTrailingZeros(bit)
        sums[mask] = (sums[mask xor bit] + values[index]) % modulus
    }
    return sums
}

private fun upperBound(array: LongArray, target: Long): Int {
    var left = 0
    var right = array.size
    while (left < right) {
        val mid = (left + right) ushr 1
        if (array[mid] <= target) left = mid + 1
        else right = mid
    }
    return left
}

fun main() {
    val fs = FastScanner()
    val n = fs.nextLong().toInt()
    val m = fs.nextLong()

    val a = LongArray(n) { fs.nextLong() % m }

    val leftSize = n / 2
    val left = a.copyOfRange(0, leftSize)
    val right = a.copyOfRange(leftSize, n)

    val leftSums = generateSums(left, m)
    val rightSums = generateSums(right, m)
    Arrays.sort(rightSums)

    var answer = 0L

    for (x in leftSums) {
        val limit = m - 1 - x
        val index = upperBound(rightSums, limit) - 1
        if (index >= 0) {
            answer = maxOf(answer, x + rightSums[index])
        }
    }

    print(answer)
}

